        eggClicks = 0
        tween(logoStroke, {Color = T.Warning, Thickness = 4}, 0.1)
        task.wait(0.1)
        tween(logoStroke, {Color = T.Accent1, Thickness = 1.5}, 0.3)
        statusMsg.Text = "🥚 shh... you found the egg! 🐞"
        tween(statusMsg, {TextColor3 = T.Warning}, 0.2)
