            local burst = Instance.new("Frame")
            burst.Size = UDim2.new(0, 6, 0, 6)
            burst.Position = UDim2.new(0.5, 0, 0.3, 0)
            burst.BackgroundColor3 = ({T.Warning, T.Neon, T.Accent1, T.Accent3})[math.random(1,4)]
            burst.BorderSizePixel = 0
            burst.ZIndex = 22
            burst.AnchorPoint = Vector2.new(0.5, 0.5)
            burst.Parent = centerPanel
            corner(burst, 3)
            local ang = (i / 16) * math.pi * 2
            local d = math.random(60, 140)
            tween(burst, {
                Position = UDim2.new(0.5, math.cos(ang)*d, 0.3, math.sin(ang)*d),
                BackgroundTransparency = 1, Size = UDim2.new(0,2,0,2)
            }, 0.8, Enum.EasingStyle.Quad)
            task.delay(0.85, function() burst:Destroy() end)
        end
